function weekday(date){if(!date)return"·";const day=new Date(`${date}T00:00:00+08:00`).getDay();return["日","一","二","三","四","五","六"][day];}
function legendMark(color){const c=new DrawContext();c.size=new Size(8,8);c.opaque=false;c.respectScreenScale=true;c.setFillColor(color);c.fillRect(new Rect(0,0,8,8));return c.getImage();}
function drawCourier(kind,size){const grid=32,unit=size/grid,c=new DrawContext();c.size=new Size(size,size);c.opaque=false;c.respectScreenScale=true;const fill=(x,y,w,h,color)=>{c.setFillColor(color);c.fillRect(new Rect(x*unit,y*unit,w*unit,h*unit));};fill(7,2,15,2,C.outline);fill(4,4,22,4,C.outline);fill(6,1,6,4,C.outline);fill(16,0,6,5,C.outline);fill(7,3,15,1,C.white);fill(5,5,20,2,C.white);fill(7,2,4,3,C.white);fill(17,1,4,4,C.white);fill(7,7,16,2,C.outline);fill(5,9,19,10,C.outline);fill(7,7,5,5,C.outline);fill(18,7,5,6,C.outline);fill(8,9,12,9,C.skin);fill(7,11,14,5,C.skin);fill(6,13,3,4,C.skin);fill(8,9,4,4,C.outline);fill(18,9,3,5,C.outline);fill(10,13,2,1,C.outline);fill(16,13,2,1,C.outline);fill(13,16,4,1,C.outline);fill(9,18,11,2,C.outline);fill(7,20,15,8,C.outline);fill(9,18,10,3,C.forecast);fill(9,20,11,7,C.actual);fill(6,21,4,5,C.outline);fill(19,20,4,6,C.outline);fill(8,27,5,4,C.outline);fill(17,27,5,4,C.outline);fill(12,20,5,2,C.white);fill(13,22,5,3,C.forecast);if(kind==="error"){fill(20,8,11,2,C.outline);fill(18,10,14,2,C.sakura);fill(25,12,1,14,C.outline);fill(24,25,3,1,C.outline);}else if(kind==="stale"){fill(23,18,8,8,C.outline);fill(24,19,6,6,C.white);fill(27,20,1,3,C.actual);fill(27,22,2,1,C.actual);}else if(kind==="empty"){fill(23,23,5,4,C.rule);}else{fill(25,8,2,18,C.outline);fill(21,11,6,2,C.actual);fill(19,8,8,2,C.forecast);fill(23,5,6,2,C.sky);fill(24,24,4,2,C.outline);}return c.getImage();}
function addStatus(parent,status,size){const s=parent.addStack();s.centerAlignContent();const dot=s.addImage(statusDot(status.kind));dot.imageSize=new Size(size-1,size-1);s.addSpacer(4);add(s,status.label,mono(size),statusColor(status.kind));}
function statusDot(kind){const c=new DrawContext();c.size=new Size(6,6);c.opaque=false;c.respectScreenScale=true;c.setFillColor(kind==="live"?C.healthy:kind==="stale"?C.forecast:kind==="error"?C.sakura:C.rule);c.fillRect(new Rect(0,0,6,6));return c.getImage();}
function statusColor(kind){return kind==="live"?UI.healthyText:kind==="stale"?UI.warnText:kind==="error"?UI.errorText:UI.muted;}
function rule(parent){const s=parent.addStack();s.size=new Size(0,1);s.backgroundColor=UI.rule;}function nextRefreshDate(){const step=REFRESH_MINUTES*60000;return new Date(Math.ceil((Date.now()+1000)/step)*step);}
function add(p,x,font,color){const t=p.addText(String(x));t.font=font;t.textColor=color;return t;}function fit(t,lines,scale){t.lineLimit=lines;t.minimumScaleFactor=scale;return t;}
function title(s){return new Font("PingFangSC-Semibold",s);}function body(s){return new Font("PingFangSC-Regular",s);}function label(s){return new Font("AvenirNext-DemiBold",s);}function numberFont(s){return new Font("AvenirNext-DemiBold",s);}function mono(s){return new Font("Menlo-Regular",s);}
function finite(x){return Number.isFinite(Number(x));}function num(x){return finite(x)?Number(x):0;}function number(n){return Math.round(num(n)).toString().replace(/\B(?=(\d{3})+(?!\d))/g,",");}
function relative(ts){if(!ts)return"未同步";const m=Math.max(0,Math.floor((Date.now()/1000-ts)/60));return m<1?"刚刚":m<60?`${m}分钟前`:m<1440?`${Math.floor(m/60)}小时前`:`${Math.floor(m/1440)}天前`;}

function loadV3Settings(){
 const fm=FileManager.local(),names=["token-tracker-v3-settings.json","token-tracker-v2-settings.json"];
 for(const name of names){
  const path=fm.joinPath(fm.documentsDirectory(),name);
  if(!fm.fileExists(path))continue;
  try{const value=JSON.parse(fm.readString(path));if(/^https?:\/\//.test(value?.apiUrl||"")&&value?.apiKey)return value;}catch(_){ }
 }
 return{apiUrl:"",apiKey:""};
}
